<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> replace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-f] --convert-graft-file</span></span>
